begin;
select set_config('app.sample_actor',gen_random_uuid()::text,true);
select set_config('app.sample_outsider',gen_random_uuid()::text,true);
select set_config('app.sample_company',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select current_setting(setting)::uuid,'authenticated','authenticated','sample+'||current_setting(setting)||'@invalid.test',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{"display_name":"SAMPLE Operator"}'::jsonb,now(),now()
from unnest(array['app.sample_actor','app.sample_outsider']) setting;
insert into public.companies(id,name,created_by) values(current_setting('app.sample_company')::uuid,'SAMPLE Equipment Factory',current_setting('app.sample_actor')::uuid);
insert into public.plants(company_id,name) values(current_setting('app.sample_company')::uuid,'SAMPLE Plant');
insert into public.company_memberships(company_id,user_id) values(current_setting('app.sample_company')::uuid,current_setting('app.sample_actor')::uuid);
insert into public.user_company_roles(company_id,user_id,role) values(current_setting('app.sample_company')::uuid,current_setting('app.sample_actor')::uuid,'admin');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('app.sample_actor'),true);
do $$
declare c uuid:=current_setting('app.sample_company')::uuid; item uuid;raw_item uuid;centre uuid;wh uuid;loc uuid;cust uuid;pkg uuid;rfq uuid;q uuid;so uuid;line uuid;wo uuid;job uuid;lot uuid;gauge_lot uuid;raw_plan uuid;plan uuid;gauge uuid;machine uuid;assignment uuid;shift uuid;allocation uuid;receipt uuid;p jsonb;
begin
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-RAW','SAMPLE material','pcs') returning id into raw_item;
 insert into public.items(company_id,sku,description,base_uom) values(c,'SAMPLE-FG','SAMPLE fastener','pcs') returning id into item;
 insert into public.customers(company_id,code,name) values(c,'SAMPLE-C','SAMPLE customer') returning id into cust;
 insert into public.work_centres(company_id,plant_id,code,name) select c,id,'SAMPLE-WC','SAMPLE centre' from public.plants where company_id=c returning id into centre;
 insert into public.warehouses(company_id,plant_id,code,name) select c,id,'SAMPLE-WH','SAMPLE warehouse' from public.plants where company_id=c returning id into wh;
 insert into public.stock_locations(company_id,warehouse_id,code,name) values(c,wh,'SAMPLE-LOC','SAMPLE location') returning id into loc;
 pkg:=public.production_command(c,'create_package',jsonb_build_object('item_id',item,'revision_label','A','basis_quantity','1','components',jsonb_build_array(jsonb_build_object('item_id',raw_item,'quantity','1','uom','pcs','scrap_allowance_pct','0')),'operations',jsonb_build_array(jsonb_build_object('sequence',10,'work_centre_id',centre,'name','SAMPLE forming'))),'pkg');
 perform public.production_command(c,'approve_package',jsonb_build_object('package_id',pkg),'pkg-approve');
 rfq:=public.create_rfq(c,'SAMPLE-R',cust,'SAMPLE request',jsonb_build_array(jsonb_build_object('item_id',item,'requested_description','SAMPLE bolt','quantity','10','uom','pcs')),'rfq');
 perform public.record_feasibility(c,rfq,'feasible',null,null,null,'SAMPLE',1,'feas');
 q:=public.create_quotation(c,rfq,'SAMPLE-Q','INR',current_date+30,jsonb_build_array(jsonb_build_object('item_id',item,'quantity','10','uom','pcs','unit_price','1')),'quote');
 perform public.approve_quotation(c,q,1,'approve-q');
 so:=public.accept_quotation_create_sales_order(c,q,'SAMPLE-SO','SAMPLE-PO',current_date+7,2,'accept');
 select id into line from public.sales_order_lines where sales_order_id=so;
 wo:=public.production_command(c,'create_work_order',jsonb_build_object('sales_order_line_id',line,'package_id',pkg,'number','SAMPLE-WO','quantity','10','start_date',current_date,'due_date',current_date+7),'wo');
 raw_plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',raw_item,'label','SAMPLE raw plan','version','A','sample_size',1,'characteristics','[{"key":"condition","label":"SAMPLE condition","type":"attribute","expected":"PASS"}]'::jsonb),'raw-plan');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',raw_plan),'raw-plan-approve');
 lot:=public.receive_finished_goods(c,raw_item,loc,'SAMPLE-RAW-LOT',10,'pcs','receive');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',raw_plan,'lot_id',lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE checked'),'inspect-raw');
 perform public.release_stock_lot(c,lot,1,'release-raw');
 perform public.production_command(c,'release_work_order',jsonb_build_object('work_order_id',wo,'revision',1),'release-wo');
 select id into job from public.job_cards where work_order_id=wo;
 gauge:=public.equipment_command(c,'create_asset',jsonb_build_object('code','SAMPLE-G','name','SAMPLE gauge','kind','gauge','work_centre_id',null,'requires_maintenance',false,'reason','SAMPLE setup'),'gauge');
 assignment:=public.equipment_command(c,'assign_job_asset',jsonb_build_object('asset_id',gauge,'job_card_id',job,'reason','SAMPLE job requirement'),'assignment');
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job,'revision',1),'missing-start');raise exception 'SAMPLE_MISSING_CALIBRATION_STARTED';exception when others then if sqlerrm not like 'EQUIPMENT_NOT_READY:%' then raise;end if;end;
 p:=jsonb_build_object('asset_id',gauge,'checked_on',current_date,'next_due',current_date+30,'passed',true,'reference','SAMPLE calibration certificate','reason','SAMPLE verified');
 perform public.equipment_command(c,'calibration',p||jsonb_build_object('checked_on',current_date-10,'next_due',current_date-1),'expired');
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job,'revision',1),'expired-start');raise exception 'SAMPLE_EXPIRED_CALIBRATION_STARTED';exception when others then if sqlerrm not like 'EQUIPMENT_NOT_READY:%' then raise;end if;end;
 begin perform public.equipment_command(c,'calibration',p-'next_due','missing-due');raise exception 'SAMPLE_MISSING_DUE_ALLOWED';exception when check_violation then null;end;
 begin perform public.equipment_command(c,'calibration',p||jsonb_build_object('checked_on',current_date+1),'future-check');raise exception 'SAMPLE_FUTURE_CHECK_ALLOWED';exception when others then if sqlerrm<>'INVALID_DATE_RANGE' then raise;end if;end;
 receipt:=public.equipment_command(c,'calibration',p,'calibrate');
 if public.equipment_command(c,'calibration',p,'calibrate')<>receipt then raise exception 'SAMPLE_CALIBRATION_RETRY_CHANGED';end if;
 begin perform public.equipment_command(c,'calibration',p||'{"passed":false}','calibrate');raise exception 'SAMPLE_CHANGED_RETRY_ALLOWED';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;
 plan:=public.quality_command(c,'create_plan',jsonb_build_object('item_id',raw_item,'label','SAMPLE gauge plan','version','B','sample_size',1,'characteristics','[{"key":"condition","label":"SAMPLE condition","type":"attribute","expected":"PASS"}]'::jsonb),'plan');
 perform public.equipment_command(c,'link_gauge_plan',jsonb_build_object('asset_id',gauge,'plan_id',plan,'reason','SAMPLE gauge required'),'bind');
 perform public.quality_command(c,'approve_plan',jsonb_build_object('plan_id',plan),'approve-plan');
 gauge_lot:=public.receive_finished_goods(c,raw_item,loc,'SAMPLE-GAUGE-LOT',1,'pcs','gauge-receive');
 perform public.equipment_command(c,'hold',jsonb_build_object('asset_id',gauge,'reason','SAMPLE damaged'),'hold');
 begin perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',plan,'lot_id',gauge_lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE checked'),'held-inspect');raise exception 'SAMPLE_HELD_GAUGE_INSPECTED';exception when others then if sqlerrm not like 'EQUIPMENT_NOT_READY:%' then raise;end if;end;
 perform public.equipment_command(c,'clear_hold',jsonb_build_object('asset_id',gauge,'reason','SAMPLE reviewed'),'clear');
 perform public.equipment_command(c,'calibration',p||'{"passed":false}','failed');
 begin perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job,'revision',1),'failed-start');raise exception 'SAMPLE_FAILED_CALIBRATION_STARTED';exception when others then if sqlerrm not like 'EQUIPMENT_NOT_READY:%' then raise;end if;end;
 perform public.equipment_command(c,'calibration',p,'passed-again');
 perform public.quality_command(c,'inspect',jsonb_build_object('plan_id',plan,'lot_id',gauge_lot,'kind','incoming','revision',1,'readings','[{"key":"condition","values":["PASS"]}]'::jsonb,'reason','SAMPLE checked'),'ready-inspect');
 machine:=public.equipment_command(c,'create_asset',jsonb_build_object('code','SAMPLE-M','name','SAMPLE machine','kind','machine','work_centre_id',centre,'requires_maintenance',true,'reason','SAMPLE configured maintenance'),'machine');
 if not exists(select 1 from jsonb_array_elements(public.get_equipment_workspace(c)->'assets') a where a->>'id'=machine::text and a->>'blocked_reason'='Maintenance evidence is missing.') then raise exception 'SAMPLE_MAINTENANCE_NOT_REQUIRED';end if;
 perform public.equipment_command(c,'maintenance',jsonb_build_object('asset_id',machine,'checked_on',current_date,'next_due',current_date+7,'passed',true,'reference','SAMPLE maintenance record','reason','SAMPLE checked'),'maintenance');
 p:=jsonb_build_object('work_centre_id',centre,'label','SAMPLE shift','from_date',current_date,'from_time','09:00','to_date',current_date,'to_time','10:00','break_minutes',10,'reason','SAMPLE configured shift');
 shift:=public.equipment_command(c,'create_shift',p,'shift');
 begin perform public.equipment_command(c,'create_shift',p||'{"label":"SAMPLE overlap"}','overlap');raise exception 'SAMPLE_OVERLAP_ALLOWED';exception when others then if sqlerrm<>'CAPACITY_SHIFT_OVERLAP' then raise;end if;end;
 allocation:=public.equipment_command(c,'allocate',jsonb_build_object('shift_id',shift,'job_card_id',job,'minutes','49.99','reason','SAMPLE estimate'),'allocation');
 begin perform public.equipment_command(c,'allocate',jsonb_build_object('shift_id',shift,'job_card_id',job,'minutes','0.02','reason','SAMPLE estimate'),'excess');raise exception 'SAMPLE_OVERBOOKED';exception when others then if sqlerrm<>'CAPACITY_EXCEEDED' then raise;end if;end;
 begin perform public.equipment_command(c,'cancel_shift',jsonb_build_object('shift_id',shift,'reason','SAMPLE cancel'),'cancel-used');raise exception 'SAMPLE_USED_SHIFT_CANCELLED';exception when others then if sqlerrm<>'CAPACITY_ALLOCATIONS_EXIST' then raise;end if;end;
 perform public.equipment_command(c,'release_allocation',jsonb_build_object('allocation_id',allocation,'reason','SAMPLE reschedule'),'release-allocation');
 perform public.equipment_command(c,'cancel_shift',jsonb_build_object('shift_id',shift,'reason','SAMPLE cancel'),'cancel');
 if not exists(select 1 from public.capacity_allocations where id=allocation) or (public.get_equipment_workspace(c)->'allocations')<>'[]'::jsonb then raise exception 'SAMPLE_RELEASE_LOST_HISTORY';end if;
 perform public.production_command(c,'start_job',jsonb_build_object('job_card_id',job,'revision',1),'start');
 begin perform public.equipment_command(c,'release_job_asset',jsonb_build_object('assignment_id',assignment,'reason','SAMPLE bypass'),'release-running');raise exception 'SAMPLE_RUNNING_ASSIGNMENT_RELEASED';exception when others then if sqlerrm<>'INVALID_TRANSITION' then raise;end if;end;
 begin delete from public.equipment_events where id=receipt;raise exception 'SAMPLE_EVIDENCE_WRITABLE';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_outsider'),true);
 if exists(select 1 from public.equipment_assets where company_id=c) then raise exception 'SAMPLE_EQUIPMENT_RLS_LEAK';end if;
 begin perform public.get_equipment_workspace(c);raise exception 'SAMPLE_EQUIPMENT_RPC_LEAK';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 begin perform public.equipment_command(c,'create_shift',p,'outsider');raise exception 'SAMPLE_OUTSIDER_WRITE';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
end $$;
rollback;
